import google.auth
from google.cloud import monitoring_v3

def aggregate_metric_stats(project_id, metric_type, start_time, end_time):
    credentials, project = google.auth.default()
    client = monitoring_v3.MetricServiceClient(credentials=credentials)
    name = f'projects/{project_id}'
    interval = {
        'start_time': start_time,
        'end_time': end_time,
    }
    request = {
        'name': name,
        'interval': interval,
        'filter': f'metric.type = "{metric_type}"',
        'aggregation': {
            'alignment_period': {'seconds': 60},
            'per_series_aligner': 'ALIGN_MEAN',
            'cross_series_reducer': 'REDUCE_NONE',
            'group_by_fields': ['resource.type'],
        },
    }
    response = client.list_time_series(request=request)
    return response.time_series

import google.auth
from google.cloud import monitoring_v3

def compare_metric_series(project_id, metric_type, start_time, end_time, filter1, filter2):
    credentials, project = google.auth.default()
    client = monitoring_v3.MetricServiceClient(credentials=credentials)
    name = f'projects/{project_id}'
    interval = {
        'start_time': start_time,
        'end_time': end_time,
    }
    request1 = {
        'name': name,
        'interval': interval,
        'filter': f'metric.type = "{metric_type}" AND {filter1}',
    }
    request2 = {
        'name': name,
        'interval': interval,
        'filter': f'metric.type = "{metric_type}" AND {filter2}',
    }
    response1 = client.list_time_series(request=request1)
    response2 = client.list_time_series(request=request2)
    return response1.time_series, response2.time_series

import os
import google.auth
from google.cloud import monitoring_v3

def get_client():
    credentials, project_id = google.auth.default()
    return monitoring_v3.MetricServiceClient(credentials=credentials)

def get_project_id():
    return os.getenv('GOOGLE_CLOUD_PROJECT')

from google.cloud.monitoring_v3 import TimeSeries

class MetricRequest:
    def __init__(self, project_id, metric_type, start_time, end_time, filter_=None):
        self.project_id = project_id
        self.metric_type = metric_type
        self.start_time = start_time
        self.end_time = end_time
        self.filter_ = filter_

class MetricResponse:
    def __init__(self, time_series):
        self.time_series = time_series

import re

def check_unsafe_text(text):
    unsafe_patterns = [r'badword1', r'badword2']
